// Generated by the Niobium FHE Application Design AI Assistant (FHEanna).
// encrypt <client_home> <features_csv> <out_dir> [max_records]
// Client input prep: enforce the standardized feature box (airtight pre-flight
// filter -- provable Chebyshev domains make any box-passing record decode-safe),
// pack column-major (ciphertext j = feature j across <=32768 record slots),
// encrypt, serialize.
#include "common.hpp"
#include <iostream>
#include <cmath>

int main(int argc, char** argv) try {
    if (helpRequested(argc, argv)) {
        std::cout << "usage: encrypt <client_home> <features_csv> <out_dir> [max_records]\n\nStage 2 of 4 (client). Checks each standardized record against the feature\nbounds, packs one feature per ciphertext (32,768 records per slot-batch),\nencrypts, and writes the ciphertexts and manifest.txt to <out_dir>.\n";
        return 0;
    }
    std::string home = argc > 1 ? argv[1] : "client_home";
    std::string csv  = argc > 2 ? argv[2] : home + "/test_features_std.csv";
    std::string out  = argc > 3 ? argv[3] : home + "/ct_in";
    size_t maxRec    = argc > 4 ? std::stoul(argv[4]) : SIZE_MAX;

    CryptoContext<DCRTPoly> cc;  mustDeserialize(cc, home + "/context.bin");
    cc->Enable(PKE); cc->Enable(KEYSWITCH); cc->Enable(LEVELEDSHE); cc->Enable(ADVANCEDSHE);
    PublicKey<DCRTPoly> pk;      mustDeserialize(pk, home + "/key_public.bin");

    // client_meta: standardized bounds + threshold (no model weights)
    std::ifstream meta(home + "/client_meta.txt");
    if (!meta) throw std::runtime_error("Cannot open " + home + "/client_meta.txt");
    int F; meta >> F;
    std::vector<double> zlo(F), zhi(F);
    for (auto& v : zlo) meta >> v;
    for (auto& v : zhi) meta >> v;

    auto rows = loadCsv(csv, maxRec);
    if (rows.empty()) throw std::runtime_error("No input records");

    // airtight box check (survey code-book bounds, standardized units)
    const double eps = 1e-9;
    size_t rejected = 0;
    std::vector<std::vector<double>> ok;
    ok.reserve(rows.size());
    for (auto& r : rows) {
        bool in = ((int)r.size() == F);
        for (int j = 0; in && j < F; ++j)
            in = (r[j] >= zlo[j] - eps && r[j] <= zhi[j] + eps);
        if (in) ok.push_back(std::move(r)); else ++rejected;
    }
    size_t n = ok.size();
    size_t nBatches = (n + SLOTS - 1) / SLOTS;
    std::cout << "encrypt: " << n << " records admitted, " << rejected
              << " rejected by feature box, " << nBatches << " slot-batch(es)\n";

    std::ofstream manifest(out + "/manifest.txt");
    if (!manifest) throw std::runtime_error("Cannot write " + out + "/manifest.txt");
    manifest << F << " " << nBatches << "\n";
    size_t total = 0;
    for (size_t b = 0; b < nBatches; ++b) {
        size_t lo = b * SLOTS, hi = std::min(n, lo + SLOTS);
        manifest << (hi - lo) << "\n";
        for (int j = 0; j < F; ++j) {
            std::vector<double> col(hi - lo);
            for (size_t i = lo; i < hi; ++i) col[i - lo] = ok[i][j];
            auto pt = cc->MakeCKKSPackedPlaintext(col);
            auto ct = cc->Encrypt(pk, pt);
            std::string path = out + "/ct_b" + std::to_string(b) + "_f" + std::to_string(j) + ".bin";
            mustSerialize(ct, path);
            total += fileSize(path);
        }
    }
    std::cout << "encrypt: wrote " << nBatches * F << " ciphertexts, "
              << total / (1024.0 * 1024.0) << " MB total\n";
    return 0;
} catch (const std::exception& e) {
    std::cerr << "encrypt: error: " << e.what() << "\n";
    return 1;
}
